Fixpoint evz (e : expr) (acc : list Z) : list Z :=
  match e with
  | ELit _ => acc
  | EVar w => Z.of_nat w :: acc
  | EAlu _ a b | EAluw _ a b | EMd _ a b | EMdw _ a b => evz a (evz b acc)
  | EExt _ _ _ a => evz a acc
